// 便捷查询
export function getMat(kind, id){ return (MAT[kind] && MAT[kind][id]) || null; }
export function floorMat(id){ return MAT.floor[id] || null; }
export function blockMat(id){ return MAT.block[id] || null; }
export function objMat(id){ return MAT.obj[id] || null; }

// 群系预设（TileGroup 概念）：返回 {floor, block, objs} 数字 id
export function biome(k){ return BIOMES[k] || null; }
